#include <cstdio>
#include <cstring>
#include <algorithm>
using namespace std;

const int MAXN=300010;
int n, K, mod;
int f[MAXN][20];
int countBits[MAXN], maxPower[MAXN];
int fact[MAXN], invFact[MAXN];

int fast_pow(int base, int exp) {
    int res=1;
    while (exp > 0) {
        if (exp & 1) res = (long long)res * base % mod;
        base = (long long)base * base % mod;
        exp >>= 1;
    }
    return res;
}

int comb(int i, int j) {
    return (long long)fact[i] * invFact[j] % mod * invFact[i - j] % mod;
}

int main() {
    scanf("%d%d%d", &n, &K, &mod);
    int i, j, k;
    int total=0;
    int mask, remaining, tmpVal, current, c1, c2;

    if (n & 1) {
        printf("%d\n", fast_pow(K, n));
        return 0;
    }

    fact[0]=1;
    for (i=1; i<=n; i++) fact[i] = (long long)fact[i-1]*i % mod;

    invFact[n] = fast_pow(fact[n], mod-2);
    for (i=n-1; i>=1; i--) invFact[i] = (long long)invFact[i+1]*(i+1) % mod;

    for (i=1; i<=n; i++) {
        for (j=0; j<=18; j++) {
            if ((1<<j) & i) countBits[i]++;
        }
    }

    for (i=1; i<=n; i++) {
        for (j=18; j>=0; j--) {
            if ((1<<j) & i) {
                maxPower[i] = 1<<j;
                break;
            }
        }
    }

    memset(f, 0, sizeof(f));
    f[0][0] = 1;

    for (i=1; i<=n; i++) {
        if ((n & i) != i) continue;
        remaining = i ^ maxPower[i];
        for (mask=remaining; ; mask=(mask-1)&remaining) {
            current = mask + maxPower[i];
            c2 = i ^ current;
            int limit = min(K-1, countBits[c2]);
            int tmp = comb(i, current);
            for (j=0; j<=limit; j++) {
                f[i][j+1] = (f[i][j+1] + (long long)f[c2][j] * tmp) % mod;
            }
            if (mask == 0) break;
        }
    }

    for (j=1; j<=min(countBits[n], K); j++) {
        total = (total + (long long)f[n][j] * comb(K, j) % mod * fact[j]) % mod;
    }

    total = (fast_pow(K, n) - total + mod) % mod;
    printf("%d\n", total);
    return 0;
}
